export type FrontierSemanticFindingV1={contractVersion:"1";ruleId:typeof FRONTIER_SEMANTIC_RULES[number];objectKind:string;objectPath:string;result:"pass"|"fail"|"blocked";sourceEventIds:string[];reasonCategory:string;candidateStatement:string|null;findingDigest:string};
