export function evaluateFrontierCitationFindings(output:FrontierStructuredOutputV1|FrontierExecutiveOutputV1,system:FrontierSystem,packet:DiscoveryStudioFrontierSourcePacketV1){const enabled=new Set(packet.enabledEvents.map(event=>event.eventId)),disabled=new Set(packet.disabledEvents.map(event=>event.eventId)),items=system==="openai-frontier-structured"?(output as FrontierStructuredOutputV1).objects:(output as FrontierExecutiveOutputV1).sourceReferencedClaims;return items.flatMap((item,index)=>{const ids=item.sourceEventIds,invalid=ids.filter(sourceId=>!enabled.has(sourceId));return invalid.length||!ids.length?[semanticFinding({ruleId:"citation-source-support",objectKind:"kind" in item?item.kind:"executive-claim",objectPath:system==="openai-frontier-structured"?`objects[${index}]`:`sourceReferencedClaims[${index}]`,result:"fail",sourceEventIds:[...ids],reasonCategory:!ids.length?"uncited-material-claim":invalid.some(id=>disabled.has(id))?"disabled-source-citation":"unknown-source-citation",candidateStatement:item.statement})]:[]})}
