export function validateFrontierSemantics(output:unknown,system:FrontierSystem,packet:DiscoveryStudioFrontierSourcePacketV1):FrontierSemanticValidationV1{assertFrontierOutput(output,system,packet);const objects=system==="openai-frontier-structured"?(output as FrontierStructuredOutputV1).objects:system==="openai-frontier-executive"?(output as FrontierExecutiveOutputV1).sourceReferencedClaims:[],enabled=new Set(packet.enabledEvents.map(event=>event.eventId)),disabled=new Set(packet.disabledEvents.map(event=>event.eventId)),unsupported:FrontierSemanticValidationV1["unsupportedClaims"]=[];for(const item of objects){if(!item.sourceEventIds.length)unsupported.push({statement:item.statement,category:"uncited"});for(const source of item.sourceEventIds)if(disabled.has(source))unsupported.push({statement:item.statement,category:"disabled-source"});else if(!enabled.has(source))unsupported.push({statement:item.statement,category:"unknown-source"})}const citations=objects.flatMap(item=>item.sourceEventIds),base={contractVersion:"2" as const,sourcePacketDigest:packet.packetDigest,system,claimCount:objects.length,citationCount:citations.length,citationCoverage:objects.length?objects.filter(item=>item.sourceEventIds.length>0).length/objects.length:1,uncitedClaimCount:unsupported.filter(item=>item.category==="uncited").length,unknownSourceCount:unsupported.filter(item=>item.category==="unknown-source").length,disabledSourceCount:unsupported.filter(item=>item.category==="disabled-source").length,inaccessibleSourceCount:0,fabricatedSourceCount:0,sourceAuthorityPreserved:unsupported.length===0,unsupportedClaims:unsupported,semanticFirewallStatus:"PASS" as const};if(unsupported.length)throw new Error("Frontier semantic citation coverage is incomplete.");return{...base,validationDigest:frontierDigest(base)}}

